from typing import List
import itertools

def solve_tsp(distance_matrix: List[List[int]]) -> int:
    if not distance_matrix or not distance_matrix[0]:
        return 0

    n = len(distance_matrix)
    cities = list(range(n))

    # Using Held-Karp algorithm approach for efficiency
    # memo[(mask, last_city)] = min_cost
    memo = {}

    def visit(mask: int, last_city: int) -> int:
        if mask == (1 << n) - 1:
            return distance_matrix[last_city][0]

        state = (mask, last_city)
        if state in memo:
            return memo[state]

        res = float('inf')
        for next_city in range(n):
            if not (mask & (1 << next_city)):
                cost = distance_matrix[last_city][next_city] + visit(mask | (1 << next_city), next_city)
                res = min(res, cost)

        memo[state] = res
        return res

    return int(visit(1, 0))
