import itertools

def solve_tsp(distance_matrix: List[List[int]]) -> int:
    if not distance_matrix or not distance_matrix[0]:
        raise ValueError("Distance matrix cannot be empty.")

    n = len(distance_matrix)
    if any(len(row) != n for row in distance_matrix):
        raise ValueError("Distance matrix must be square.")

    # memoization table: (mask, last_city) -> min_cost
    memo: Dict[Tuple[int, int], int] = {}

    def get_min_cost(mask: int, pos: int) -> int:
        # All cities visited
        if mask == (1 << n) - 1:
            return distance_matrix[pos][0]

        state = (mask, pos)
        if state in memo:
            return memo[state]

        res = float('inf')
        for next_city in range(n):
            if not (mask & (1 << next_city)):
                new_cost = distance_matrix[pos][next_city] + get_min_cost(mask | (1 << next_city), next_city)
                res = min(res, new_cost)

        memo[state] = int(res)
        return memo[state]

    return get_min_cost(1, 0)
