def maximize_oil_production(initial_wells: int, initial_yield: int, decrease_per_well: int) -> int:
    """
    Calculates the number of additional wells to maximize total daily oil production.
    Total Production P(x) = (initial_wells + x) * (initial_yield - x * decrease_per_well)
    This is a downward opening parabola: P(x) = -dx^2 + (initial_yield - d*initial_wells)x + C
    The vertex occurs at x = -b / 2a
    """
    if decrease_per_well <= 0:
        raise ValueError("Decrease per well must be a positive integer.")

    # P(x) = -decrease_per_well * x^2 + (initial_yield - decrease_per_well * initial_wells) * x + constant
    # Vertex x = -(initial_yield - decrease_per_well * initial_wells) / (2 * -decrease_per_well)
    # x = (initial_yield - decrease_per_well * initial_wells) / (2 * decrease_per_well)

    numerator = initial_yield - (decrease_per_well * initial_wells)
    denominator = 2 * decrease_per_well

    optimal_x = numerator / denominator

    # Since x must be an integer, check the two closest integers
    x1 = int(optimal_x)
    x2 = x1 + 1

    def total_production(x: int) -> int:
        if x < 0:
            return -1
        return (initial_wells + x) * (initial_yield - (x * decrease_per_well))

    if total_production(x1) >= total_production(x2):
        return max(0, x1)
    else:
        return max(0, x2)
