from typing import Optional

def calculate_inverse_prob(start: int, end: int) -> Optional[int]:
    if start > end:
        return None

    total_count = end - start + 1
    favorable_count = 0

    # Constraints:
    # 1 <= a1 <= 9
    # 0 <= a2, a3, a4, a5 <= 9
    # a1 <= a2 + 1  => a1 - 1 <= a2
    # a2 + 1 <= a3 - 7 => a2 + 8 <= a3
    # a3 - 7 < a4 => a3 - 6 <= a4
    # a4 <= a5 + 2 => a4 - 2 <= a5

    for a1 in range(1, 10):
        for a2 in range(max(0, a1 - 1), 10):
            for a3 in range(a2 + 8, 10):
                for a4 in range(a3 - 6, 10):
                    for a5 in range(max(0, a4 - 2), 10):
                        num = a1 * 10000 + a2 * 1000 + a3 * 100 + a4 * 10 + a5
                        if start <= num <= end:
                            favorable_count += 1

    if favorable_count == 0:
        return None

    probability = favorable_count / total_count
    return round(1 / probability)
