from typing import Union

def calculate_tax_rate(quantity: int) -> float:
    """Determines the tax rate based on the quantity sold."""
    if quantity < 100:
        return 0.10
    elif quantity < 300:
        return 0.08
    else:
        return 0.05

def calculate_profit(quantity: int, fixed_cost: float, variable_cost: float, price: float) -> float:
    """Calculates the profit for a given quantity."""
    revenue = quantity * price
    tax = revenue * calculate_tax_rate(quantity)
    total_cost = fixed_cost + (quantity * variable_cost)
    return revenue - tax - total_cost

def solve_min_products(fixed_cost: float, variable_cost: float, price: float) -> int:
    """
    Finds the minimum number of products x (x ∈ N*) to achieve profit > 0.
    """
    if price <= variable_cost:
        raise ValueError("Price must be greater than variable cost to ever achieve profit.")

    quantity = 1
    while True:
        if calculate_profit(quantity, fixed_cost, variable_cost, price) > 0:
            return quantity
        quantity += 1
        if quantity > 1_000_000:  # Safety break
            raise RuntimeError("No solution found within reasonable bounds.")
