def solve_shortest_path(distances: Dict[Tuple[str, str], int]) -> int:
    nodes = ['A', 'B', 'C', 'D']
    start_node = 'M'

    # Ensure bidirectional access for distance lookup
    full_distances = {}
    for (u, v), d in distances.items():
        full_distances[(u, v)] = d
        full_distances[(v, u)] = d

    min_total_distance = float('inf')

    for path in itertools.permutations(nodes):
        # Check one-way restriction: A to B only
        # If path contains B then A, it violates the rule
        if 'A' in path and 'B' in path:
            if path.index('B') < path.index('A'):
                continue

        current_distance = 0
        try:
            # Distance from M to first node
            current_distance += full_distances[(start_node, path[0])]

            # Distance between consecutive nodes
            for i in range(len(path) - 1):
                current_distance += full_distances[(path[i], path[i+1])]

            if current_distance < min_total_distance:
                min_total_distance = current_distance
        except KeyError:
            continue

    return int(min_total_distance)
