import itertools
from typing import Dict, Tuple

def solve_shortest_path(distances: Dict[Tuple[str, str], int]) -> int:
    """
    Finds the shortest path visiting A, B, C, and D exactly once starting from M.
    Constraint: A -> B is allowed, but B -> A is not.
    """
    nodes = ['A', 'B', 'C', 'D']
    min_distance = float('inf')

    # Generate all permutations of the 4 families
    for path in itertools.permutations(nodes):
        # Check the one-way restriction: B cannot come before A
        # If A is in the path, B cannot appear at an index lower than A
        if 'A' in path and 'B' in path:
            if path.index('B') < path.index('A'):
                continue

        current_dist = 0
        valid_path = True

        # Distance from M to first node
        start_node = path[0]
        if ('M', start_node) in distances:
            current_dist += distances[('M', start_node)]
        else:
            valid_path = False

        # Distance between consecutive nodes
        if valid_path:
            for i in range(len(path) - 1):
                u, v = path[i], path[i+1]
                # Check if edge exists (handle bidirectional if not specified)
                if (u, v) in distances:
                    current_dist += distances[(u, v)]
                elif (v, u) in distances:
                    current_dist += distances[(v, u)]
                else:
                    valid_path = False
                    break

        if valid_path:
            min_distance = min(min_distance, current_dist)

    if min_distance == float('inf'):
        raise ValueError("No valid path found.")

    return int(min_distance)
