    min_distance = float('inf')

    # Ensure all bidirectional distances are accounted for if not explicitly provided
    full_distances = {}
    for (u, v), dist in distances.items():
        full_distances[(u, v)] = dist
        if (v, u) not in distances and not (u == 'A' and v == 'B'):
            full_distances[(v, u)] = dist

    for path in itertools.permutations(locations):
        # Check constraint: if A and B are in the path, A must appear before B
        if 'A' in path and 'B' in path:
            if path.index('A') > path.index('B'):
                continue

        try:
            current_dist = 0
            # Start from M
            current_dist += full_distances[('M', path[0])]

            # Visit families
            for i in range(len(path) - 1):
                current_dist += full_distances[(path[i], path[i+1])]

            if current_dist < min_distance:
                min_distance = int(current_dist)
        except KeyError:
            continue

    return int(min_distance)
